// Additional standalone CSS/native controls. Keep this API metadata aligned with extras-src/*.js.
const make = (c) => {
  const tag = '<' + c.tag + '>';
  const api = {
    runtime: 'lightweight',
    runtimeNotes: 'This standalone file embeds the compact Pinmotion Extras base and this component implementation. It does not initialize or embed PinballKit, its WebGL runtime, shader source or recorded audio. Its component-specific backglass emblem and metal deck use the Pinball UI mechanical visual language. When PinballKit is already present, the backglass chrome-ball marker reuses its shared WebGL shader and user actions can reuse its sound effects. When loaded alone, the control remains self-contained and uses the CSS chrome-ball fallback.',
    commonLimits: [],
    overview: c.overview,
    tags: [tag],
    quickStart: '<script src="' + c.id + '.js"></script>\\n' + c.demo.html,
    example: c.example,
    attributes: c.attributes,
    attributeUpdates: c.attributeUpdates,
    properties: c.properties || [],
    methods: c.methods || [],
    events: c.events || [],
    input: c.input,
    keyboard: c.keyboard,
    forms: c.forms,
    styling: 'The component sits in the shared Pinball UI metal deck with brushed-steel edges, four recessed fasteners, a component-specific backglass emblem, three pilot lamps, a chrome ball marker and a dark inset playfield. If PinballKit is already present, the marker uses the original shared chrome-ball shader; otherwise it falls back to CSS. ' + c.styling,
    motion: c.motion || 'The component uses native browser controls and CSS transitions. No continuous scripted physics or automatic motion is required.',
    notes: c.notes || [],
    happens: c.happens || [],
    limits: c.limits || []
  };
  return {
    id: c.id, name: c.name, tag: c.tag, kind: c.kind,
    categories: c.categories || ['web-components','ui-components','pinball-inspired'],
    size: { gallery: c.gallerySize || 'min(280px, 80vw)', page: c.pageSize || 'min(360px, 90vw)' },
    sub: c.overview, desc: c.overview,
    docs: 'then use ' + tag + ' and read its documented properties or events.',
    intro: [c.overview],
    demo: c.demo,
    wire: c.wire,
    use: '<script src="' + c.id + '.js"></script>\\n' + c.demo.html,
    js: c.example,
    attrs: [],
    notes: c.notes || [],
    happens: c.happens || [],
    limits: c.limits || [],
    api
  };
};

